import { createClient } from "https://esm.sh/@supabase/supabase-js@2.57.4";
import { SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, DELETE_ACCOUNT_FUNCTION, RTC_CONFIG } from "./config.js";

const sb=createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const PAGES=[["home","⌂","الرئيسية"],["discover","⌕","اكتشف"],["reels","▷","ريلز"],["moments","◫","اللحظات"],["majlis","◉","المجالس"],["play","✦","الألعاب"],["podcasts","◒","البودكاست"],["messages","✉","الرسائل"],["serious","♡","Serious Mode"]];
const S={user:null,profile:null,staff:null,page:"home",profiles:[],media:new Map(),conversations:[],activeConversation:null,chatChannel:null,globalChannel:null,authMode:"login",recorder:null,recordChunks:[],activeCall:null,pendingCall:null,callChannel:null,majlisRoom:null,majlisPeers:new Map(),majlisStream:null,majlisChannel:null};
const esc=(v="")=>String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const age=d=>d?Math.floor((Date.now()-new Date(d))/(365.25*864e5)):0;
const intent=v=>v==="marriage"?"جاهز للزواج":v==="serious"?"منفتح لشيء جاد":"أكتشف وأتعرف";
const pathLabel=v=>v==="official"?"زواج رسمي":v==="misyar"?"مسيار":"نقاش مع عهد";
const statusLabel=v=>({requested:"طلب جديد",mutual_interest:"اهتمام متبادل",guided:"إرشاد وتوافق",family_stage:"مرحلة الأسرة",contract_stage:"مرحلة العقد",completed:"مكتمل",closed:"مغلق"})[v]||v;
const toast=m=>{const e=$("#toast");e.textContent=m;e.classList.add("show");setTimeout(()=>e.classList.remove("show"),2300)};
const authErrorMessage=(m="")=>{const x=String(m).toLowerCase();if(x.includes("email rate limit"))return "تم الوصول مؤقتًا إلى حد إرسال رسائل التأكيد. حاول بعد قليل.";if(x.includes("invalid login credentials"))return "البريد الإلكتروني أو كلمة المرور غير صحيحة.";if(x.includes("email address")&&x.includes("invalid"))return "عنوان البريد الإلكتروني غير صالح.";if(x.includes("password")&&x.includes("weak"))return "اختر كلمة مرور أقوى.";if(x.includes("user already registered"))return "هذا البريد مسجل بالفعل. استخدم تسجيل الدخول.";return m||"تعذر إكمال عملية الحساب."};
const modal=(h,w=false)=>{$("#modal").innerHTML=`<div class="dialog ${w?"wide":""}"><button class="modal-close">×</button>${h}</div>`;$("#modal").classList.remove("hidden")};
const closeModal=()=>{$("#modal").classList.add("hidden");$("#modal").innerHTML=""};
const dateText=t=>new Intl.DateTimeFormat("ar-SA",{dateStyle:"medium"}).format(new Date(t));

async function signedUrl(path){if(!path)return null;if(S.media.has(path))return S.media.get(path);const {data,error}=await sb.storage.from("ahad-media").createSignedUrl(path,3600);if(error)return null;S.media.set(path,data.signedUrl);return data.signedUrl}
async function hydrateMedia(root=document){for(const e of $$('[data-media]',root)){if(e.dataset.hydrated)continue;const u=await signedUrl(e.dataset.media);if(!u)continue;if(["IMG","VIDEO","AUDIO"].includes(e.tagName))e.src=u;else e.innerHTML=`<img src="${u}" alt="">`;e.dataset.hydrated="1"}}
function avatar(p,size=""){const has=!!p?.avatar_path;return `<span class="avatar ${size}" ${has?`data-media="${esc(p.avatar_path)}"`:""}>${has?"":esc((p?.display_name||"ع").trim()[0]||"ع")}</span>`}
function compatibility(p){if(!S.profile)return 50;let n=46;if(p.lifestyle_style===S.profile.lifestyle_style)n+=10;if(p.culture_style===S.profile.culture_style)n+=9;if(p.faith_style===S.profile.faith_style)n+=8;if(p.intent===S.profile.intent)n+=7;const mine=new Set(S.profile.interests||[]);n+=Math.min(18,(p.interests||[]).filter(x=>mine.has(x)).length*4);const a=age(p.birth_date);if(a>=S.profile.preferred_min_age&&a<=S.profile.preferred_max_age)n+=5;return Math.max(48,Math.min(98,n))}
const memberAge=p=>p?.show_age===false?"العمر مخفي":age(p?.birth_date), city=p=>p?.show_city===false?"الموقع مخفي":(p?.city||p?.country_code||"العالم");
async function upload(file,folder){if(!file?.size)throw new Error("اختر ملفًا أولًا.");if(file.size>20*1024*1024)throw new Error("الحد الحالي للملف 20MB.");const ext=(file.name?.split(".").pop()||file.type.split("/").pop()||"bin").toLowerCase(),p=`${S.user.id}/${folder}/${crypto.randomUUID()}.${ext}`;const {error}=await sb.storage.from("ahad-media").upload(p,file,{contentType:file.type||"application/octet-stream"});if(error)throw error;return p}

async function loadProfile(){const {data,error}=await sb.from("profiles").select("*").eq("id",S.user.id).maybeSingle();if(error)throw error;S.profile=data||null}
async function loadStaff(){const {data}=await sb.from("staff_members").select("role,display_name,active").eq("user_id",S.user.id).maybeSingle();S.staff=data?.active?data:null}
async function loadProfiles(){const {data,error}=await sb.from("profiles").select("*").neq("id",S.user.id).eq("is_discoverable",true).limit(100);if(error)throw error;S.profiles=(data||[]).filter(p=>{const a=age(p.birth_date);if(S.profile?.preferred_genders?.length&&!S.profile.preferred_genders.includes(p.gender))return false;if(S.profile?.preferred_countries?.length&&!S.profile.preferred_countries.includes(p.country_code))return false;if(S.profile?.require_verified&&!p.verified)return false;if(S.profile&&(a<S.profile.preferred_min_age||a>S.profile.preferred_max_age))return false;return true}).sort((a,b)=>compatibility(b)-compatibility(a))}
async function loadConversations(){const {data,error}=await sb.from("conversation_members").select("conversation_id,role,conversations(id,kind,title,created_at)").eq("user_id",S.user.id);if(error)throw error;S.conversations=data||[]}
function showOnly(id){["landingView","authView","onboarding","app"].forEach(x=>$("#"+x).classList.toggle("hidden",x!==id))}
function maxBirth(){const d=new Date();d.setFullYear(d.getFullYear()-18);$('[name="birth_date"]').max=d.toISOString().slice(0,10)}
async function boot(){try{const {data:{session}}=await sb.auth.getSession();S.user=session?.user||null;$("#boot").classList.add("hidden");if(!S.user){showOnly("landingView");return}if(S.user.is_anonymous){await sb.auth.signOut();showOnly("landingView");toast("عهد لا تستخدم حسابات مجهولة.");return}await Promise.all([loadProfile(),loadStaff()]);if(!S.profile){showOnly("onboarding");maxBirth();return}await Promise.all([loadProfiles(),loadConversations()]);showOnly("app");renderChrome();await render();subscribeGlobal();listenIncomingCalls();sb.from("profiles").update({last_seen_at:new Date().toISOString()}).eq("id",S.user.id)}catch(e){console.error(e);$("#boot").classList.add("hidden");showOnly("landingView");toast(e.message||"تعذر تشغيل عهد")}}

function renderChrome(){const desktop=PAGES.map(([id,ic,l])=>`<button class="nav-item nav-action ${S.page===id?"active":""}" data-page="${id}"><i>${ic}</i><span>${l}</span></button>`).join("")+(S.staff?`<button class="nav-item nav-action ${S.page==="staff"?"active":""}" data-page="staff"><i>⚙</i><span>لوحة عهد</span></button>`:"");$("#desktopNav").innerHTML=desktop;$("#mobileNav").innerHTML=PAGES.slice(0,5).map(([id,ic,l])=>`<button class="nav-action ${S.page===id?"active":""}" data-page="${id}" aria-label="${l}">${ic}</button>`).join("");$("#currentUserCard").innerHTML=`<div class="me-card">${avatar(S.profile,"md")}<div><b>${esc(S.profile.display_name)}</b><small>${esc(city(S.profile))} · ${intent(S.profile.intent)}</small></div><button class="text-button nav-action" data-page="profile">تعديل</button></div>`;$("#rightSuggestions").innerHTML=S.profiles.slice(0,3).map(p=>`<div class="suggestion">${avatar(p)}<div><b>${esc(p.display_name)}</b><small>${compatibility(p)}% AHAD ENERGY</small></div><button class="text-button profile-like" data-id="${p.id}">تعارف</button></div>`).join("")||`<small class="muted">ستظهر الاقتراحات عند انضمام أعضاء حقيقيين مطابقين لتفضيلاتك.</small>`;hydrateMedia()}
async function render(){renderChrome();const labels={home:"الرئيسية",discover:"اكتشف",reels:"ريلز",moments:"اللحظات",majlis:"المجالس",play:"الألعاب",podcasts:"البودكاست",messages:"الرسائل",serious:"Serious Mode",profile:"ملفي",staff:"لوحة عهد"};$("#pageTitle").textContent=labels[S.page]||"عهد";const fn={home:renderHome,discover:renderDiscover,reels:renderReels,moments:renderMoments,majlis:renderMajlis,play:renderPlay,podcasts:renderPodcasts,messages:renderMessages,serious:renderSerious,profile:renderProfile,staff:renderStaff}[S.page];if(fn)await fn();await hydrateMedia($("#view"))}

async function getMoments(kind=null){let q=sb.from("moments").select("id,author_id,body,media_path,kind,metadata,expires_at,created_at,profiles:author_id(display_name,avatar_path,city,show_city),moment_reactions(user_id,reaction),moment_comments(id)").order("created_at",{ascending:false}).limit(50);if(kind)q=q.eq("kind",kind);const {data,error}=await q;if(error)throw error;return data||[]}
async function getStories(){const {data,error}=await sb.from("moments").select("id,author_id,body,media_path,metadata,created_at,profiles:author_id(display_name,avatar_path)").eq("kind","story").gt("expires_at",new Date().toISOString()).order("created_at",{ascending:false}).limit(30);if(error)throw error;return data||[]}
const storiesHTML=xs=>`<div class="stories"><button class="story" id="createStory"><div class="story-ring"><div>＋</div></div><small>قصتك</small></button>${xs.map(x=>`<button class="story open-story" data-id="${x.id}"><div class="story-ring"><div ${x.profiles?.avatar_path?`data-media="${esc(x.profiles.avatar_path)}"`:""}>${x.profiles?.avatar_path?"":esc((x.profiles?.display_name||"ع")[0])}</div></div><small>${esc(x.profiles?.display_name||"عضو")}</small></button>`).join("")}</div>`;
function postHTML(m){const liked=(m.moment_reactions||[]).some(r=>r.user_id===S.user.id),media=m.media_path?`<div class="post-media">${m.kind==="reel"?`<video data-media="${esc(m.media_path)}" controls playsinline></video>`:`<img data-media="${esc(m.media_path)}" alt="لحظة من عهد">`}</div>`:"";return `<article class="post"><div class="post-head">${avatar(m.profiles)}<div><b>${esc(m.profiles?.display_name||"عضو")}</b><small>${esc(m.profiles?.city||"AHAD")}</small></div><button class="text-button">•••</button></div>${media}<div class="post-actions"><button class="moment-like ${liked?"liked":""}" data-id="${m.id}">${liked?"♥":"♡"}</button><button class="moment-comments" data-id="${m.id}">◯</button><button class="moment-share" data-id="${m.id}">⌁</button><span style="flex:1"></span><button class="moment-save" data-id="${m.id}">☆</button></div><div class="post-body">${m.body?`<b>${esc(m.profiles?.display_name||"")}</b>${esc(m.body)}`:""}${m.kind==="poll"?`<div class="poll-options" data-poll="${m.id}"></div>`:""}<span class="meta-line">${(m.moment_reactions||[]).length} إعجاب · ${(m.moment_comments||[]).length} تعليق</span></div></article>`}
async function hydratePolls(ms){for(const m of ms.filter(x=>x.kind==="poll")){const {data}=await sb.from("poll_options").select("id,label,poll_votes(user_id)").eq("moment_id",m.id).order("sort_order"),e=$(`[data-poll="${m.id}"]`);if(e)e.innerHTML=(data||[]).map(o=>`<button class="poll-vote" data-moment="${m.id}" data-option="${o.id}">${esc(o.label)} · ${(o.poll_votes||[]).length}</button>`).join("")}}
async function renderHome(){const [st,ms]=await Promise.all([getStories(),getMoments()]),feed=ms.filter(m=>m.kind!=="story");$("#view").innerHTML=storiesHTML(st)+`<div class="composer">${avatar(S.profile)}<button id="openComposer" class="composer-prompt">شارك لحظة من يومك...</button><button id="quickPhoto" class="button soft">صورة</button></div><div class="feed-layout"><div class="feed">${feed.length?feed.map(postHTML).join(""):`<div class="empty"><div class="logo-glyph">ع</div><h3>هذا المجتمع يبدأ بأعضائه الحقيقيين.</h3><p>لا توجد منشورات بعد. لن تملأ عهد المنصة بحسابات أو قصص مزيفة.</p><button class="button primary" id="firstPost">أنشئ أول لحظة</button></div>`}</div><aside class="side-modules"><article class="module"><span class="eyebrow">AHAD VIBE™</span><h3>الجاذبية ليست كل شيء.</h3><p>التوافق يوازن بين أسلوب الحياة، الثقافة، القيم، الاهتمامات والنية.</p><button class="button soft nav-action" data-page="discover">اكتشف توافقك</button></article><article class="module"><span class="eyebrow">MAJLIS</span><h3>تعارف وسط الحياة.</h3><p>ادخل مجلسًا نصيًا أو صوتيًا صغيرًا بدل أسئلة المقابلات التقليدية.</p><button class="button soft nav-action" data-page="majlis">المجالس</button></article><article class="module"><span class="eyebrow">PLAY</span><h3>اكسر الجليد بلعبة.</h3><button class="button soft nav-action" data-page="play">ابدأ</button></article></aside></div>`;await hydratePolls(feed)}
function peopleHTML(ps){return ps.length?ps.map(p=>`<article class="person-card"><div class="person-media ${p.blur_photos_until_match&&p.avatar_path?"blurred":""}">${p.avatar_path?`<img data-media="${esc(p.avatar_path)}">`:esc((p.display_name||"ع")[0])}<span class="energy">${compatibility(p)}% ENERGY</span></div><div class="person-copy"><h3>${esc(p.display_name)} ${p.verified?"✓":""}</h3><div class="muted">${memberAge(p)} · ${esc(city(p))}</div><div class="tags">${[p.appearance_style,p.lifestyle_style,p.culture_style,p.faith_style].filter(Boolean).slice(0,4).map(x=>`<span>${esc(x)}</span>`).join("")}</div><div class="person-actions"><button class="button soft view-profile" data-id="${p.id}">الملف</button><button class="button primary profile-like" data-id="${p.id}">♡ تعارف</button></div></div></article>`).join(""):`<div class="empty"><h3>لا توجد نتائج الآن.</h3><p>ستظهر الحسابات الحقيقية عند مطابقة تفضيلاتك.</p></div>`}
async function renderDiscover(){$("#view").innerHTML=`<div class="section-head"><div><h2>اكتشف على طريقتك.</h2><p>تفضيلات وليست أحكامًا: نمط حياة، ثقافة، تدين، مظهر، عمر ومكان.</p></div><span class="chip">AHAD ENERGY™</span></div><div class="filters"><input id="filterSearch" placeholder="اسم أو مدينة أو ستايل"><select id="filterGender"><option value="">الجميع</option><option value="woman">نساء</option><option value="man">رجال</option></select><select id="filterLife"><option value="">كل أنماط الحياة</option><option>محافظ</option><option>متوازن</option><option>اجتماعي</option><option>منفتح</option><option>عالمي</option></select><select id="filterCulture"><option value="">كل العقليات</option><option>محلية</option><option>عربية معاصرة</option><option>دولية</option><option>متعددة الثقافات</option><option>غربية</option></select><select id="filterFaith"><option value="">كل الممارسات</option><option>ملتزم</option><option>متوازن</option><option>روحي</option><option>غير متدين</option></select><select id="filterIntent"><option value="">كل النوايا</option><option value="exploring">استكشاف</option><option value="serious">جاد</option><option value="marriage">زواج</option></select><input id="filterCountry" maxlength="2" placeholder="SA"><select id="filterVerified"><option value="">الجميع</option><option value="yes">موثق فقط</option></select></div><div id="peopleGrid" class="people-grid">${peopleHTML(S.profiles)}</div>`}
function applyFilters(){const s=($("#filterSearch")?.value||"").toLowerCase(),g=$("#filterGender")?.value,l=$("#filterLife")?.value,k=$("#filterCulture")?.value,f=$("#filterFaith")?.value,i=$("#filterIntent")?.value,c=($("#filterCountry")?.value||"").toUpperCase(),v=$("#filterVerified")?.value,ps=S.profiles.filter(p=>(!s||`${p.display_name} ${p.city||""} ${p.appearance_style||""}`.toLowerCase().includes(s))&&(!g||p.gender===g)&&(!l||p.lifestyle_style===l)&&(!k||p.culture_style===k)&&(!f||p.faith_style===f)&&(!i||p.intent===i)&&(!c||p.country_code===c)&&(!v||p.verified));$("#peopleGrid").innerHTML=peopleHTML(ps);hydrateMedia($("#peopleGrid"))}
async function renderReels(){const xs=await getMoments("reel");$("#view").innerHTML=`<div class="section-head"><div><h2>Reels</h2><p>مقاطع قصيرة من أعضاء عهد الحقيقيين.</p></div><button class="button primary" id="newReel">+ Reel</button></div><div class="reels-grid">${xs.length?xs.map(m=>`<article class="reel"><video data-media="${esc(m.media_path)}" controls playsinline></video><label>${esc(m.profiles?.display_name||"عضو")}</label></article>`).join(""):`<div class="empty"><h3>لا توجد Reels بعد.</h3></div>`}</div>`}
async function renderMoments(){const xs=await getMoments();$("#view").innerHTML=`<div class="section-head"><div><h2>اللحظات</h2><p>صور، يوميات، أسئلة وPolls.</p></div><button class="button primary" id="newMoment">+ لحظة</button></div><div class="feed">${xs.length?xs.map(postHTML).join(""):`<div class="empty">لا توجد لحظات بعد.</div>`}</div>`;await hydratePolls(xs)}
async function renderMajlis(){const {data,error}=await sb.from("majalis").select("*,majlis_presence(user_id,voice_role,muted)").order("created_at",{ascending:false}).limit(50);if(error)throw error;$("#view").innerHTML=`<div class="section-head"><div><h2>AHAD MAJLIS™</h2><p>مجالس نصية وصوتية صغيرة للتعارف الطبيعي.</p></div><button class="button primary" id="createMajlis">+ مجلس</button></div><div class="grid2">${(data||[]).length?(data||[]).map(x=>`<article class="card"><div class="majlis-live"><span class="live-dot"></span><span class="chip">${esc(x.access||"open")}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.description||"")}</p><small class="muted">${esc(x.city||"عالمي")} · ${(x.majlis_presence||[]).length} في الصوت</small><br><br><button class="button soft open-majlis" data-id="${x.id}">فتح المجلس</button></article>`).join(""):`<div class="empty"><h3>أنشئ أول مجلس.</h3></div>`}</div>`}
async function renderPlay(){const {data,error}=await sb.from("games").select("*").eq("active",true);if(error)throw error;$("#view").innerHTML=`<div class="section-head"><div><h2>AHAD PLAY™</h2><p>ألعاب وتحديات تجعل الحوار أخف وتضيف إشارات للتوافق.</p></div></div><div class="grid2">${(data||[]).map(g=>`<article class="card"><span class="chip">GAME</span><h3>${esc(g.title)}</h3><p>${esc(g.description||"")}</p><button class="button primary start-game" data-id="${g.id}">ابدأ</button></article>`).join("")}<article class="card"><span class="chip">تسليك</span><h3>خفيف اليوم 😄</h3><p>لو قال لك «أنا سريع بالرد» وآخر ظهور أمس… Green Flag ولا تحديث نظام؟</p></article><article class="card"><span class="chip">POLL</span><h3>سؤال اليوم</h3><p>من يبدأ الرسالة الأولى بعد الـMatch؟</p><button class="button soft" id="createPoll">اصنع Poll</button></article></div>`}
async function renderPodcasts(){const {data,error}=await sb.from("podcasts").select("*").eq("is_published",true).order("published_at",{ascending:false});if(error)throw error;$("#view").innerHTML=`<div class="section-head"><div><h2>بودكاست عهد</h2><p>ديني، اجتماعي، ثقافي وتوعوي بلغة وسطية.</p></div>${S.staff?`<button class="button primary" id="addPodcast">+ حلقة</button>`:""}</div><div class="grid2">${(data||[]).length?(data||[]).map(p=>`<article class="card"><span class="chip">${esc(p.category)}</span><h3>${esc(p.title)}</h3><p>${esc(p.description||"")}</p>${p.audio_path?`<audio class="podcast-audio" data-id="${p.id}" data-media="${esc(p.audio_path)}" controls style="width:100%"></audio>`:p.media_url?`<audio class="podcast-audio" data-id="${p.id}" src="${esc(p.media_url)}" controls style="width:100%"></audio>`:""}</article>`).join(""):`<div class="empty"><h3>المكتبة جاهزة.</h3><p>لا توجد حلقات منشورة بعد.</p></div>`}</div>`;await restorePodcastProgress()}
async function restorePodcastProgress(){for(const a of $$(".podcast-audio")){const {data}=await sb.from("podcast_progress").select("position_seconds").eq("podcast_id",a.dataset.id).eq("user_id",S.user.id).maybeSingle();if(data?.position_seconds)a.addEventListener("loadedmetadata",()=>{if(data.position_seconds<a.duration)a.currentTime=data.position_seconds},{once:true});let last=0;a.addEventListener("timeupdate",async()=>{if(Date.now()-last<10000)return;last=Date.now();await sb.from("podcast_progress").upsert({podcast_id:a.dataset.id,user_id:S.user.id,position_seconds:Math.floor(a.currentTime)})})}}

async function conversationName(x){if(x.conversations?.kind!=="private")return x.conversations?.title||"مجموعة";const {data}=await sb.from("conversation_members").select("user_id,profiles:user_id(display_name)").eq("conversation_id",x.conversation_id).neq("user_id",S.user.id).limit(1);return data?.[0]?.profiles?.display_name||"محادثة خاصة"}
async function renderMessages(){await loadConversations();const list=[];for(const x of S.conversations)list.push({...x,display:await conversationName(x)});$("#view").innerHTML=`<div class="section-head"><div><h2>الرسائل</h2><p>خاص، مجموعات ومجالس — داخل عهد.</p></div><button class="button primary" id="newGroup">+ مجموعة</button></div><div class="chat-shell"><div class="chat-list">${list.length?list.map(x=>`<button class="chat-item open-chat ${S.activeConversation===x.conversation_id?"active":""}" data-id="${x.conversation_id}">${avatar({display_name:x.display})}<div><b>${esc(x.display)}</b><small>${esc(x.conversations?.kind||"")}</small></div></button>`).join(""):`<div class="chat-item"><small>لا توجد محادثات بعد.<br>الإعجاب المتبادل يفتح محادثة خاصة تلقائيًا.</small></div>`}</div><div id="chatPane" class="chat-pane"><div class="empty"><h3>اختر محادثة.</h3><p>نص، صور، فيديو وVoice Notes داخل عهد.</p></div></div></div>`;if(S.activeConversation)await openChat(S.activeConversation)}
function messageHTML(m){let c="";if(m.message_type==="image")c=`<img data-media="${esc(m.media_path)}">`;else if(m.message_type==="video")c=`<video data-media="${esc(m.media_path)}" controls playsinline></video>`;else if(m.message_type==="audio")c=`<audio data-media="${esc(m.media_path)}" controls></audio>`;else c=esc(m.body||"");return `<div class="bubble ${m.sender_id===S.user.id?"mine":""}">${c}</div>`}
async function otherMember(id){const {data}=await sb.from("conversation_members").select("user_id,profiles:user_id(display_name,avatar_path,allow_calls)").eq("conversation_id",id).neq("user_id",S.user.id).limit(1);return data?.[0]||null}
async function openChat(id){S.activeConversation=id;if(S.chatChannel)await sb.removeChannel(S.chatChannel);const {data,error}=await sb.from("messages").select("id,sender_id,body,message_type,media_path,created_at").eq("conversation_id",id).order("created_at");if(error)throw error;const other=await otherMember(id);$("#chatPane").innerHTML=`<div class="chat-head"><div><b>${esc(other?.profiles?.display_name||"محادثة داخل عهد")}</b><small class="muted"> · داخل عهد</small></div><div><button class="button soft direct-call" data-conv="${id}" data-mode="audio">☎ صوت</button> <button class="button soft direct-call" data-conv="${id}" data-mode="video">▣ فيديو</button></div></div><div id="chatMessages" class="chat-messages">${(data||[]).map(messageHTML).join("")}</div><form id="chatForm" class="chat-form"><button type="button" class="chat-tool" id="chatMedia">＋</button><button type="button" class="chat-tool" id="voiceNote">🎙</button><input id="chatText" maxlength="4000" placeholder="اكتب داخل عهد..."><button class="chat-send">➤</button></form>`;await hydrateMedia($("#chatPane"));S.chatChannel=sb.channel(`chat:${id}`).on("postgres_changes",{event:"INSERT",schema:"public",table:"messages",filter:`conversation_id=eq.${id}`},()=>openChat(id)).subscribe();const box=$("#chatMessages");if(box)box.scrollTop=box.scrollHeight}
async function sendChatMedia(f){const p=await upload(f,"messages"),type=f.type.startsWith("video")?"video":"image",{error}=await sb.from("messages").insert({conversation_id:S.activeConversation,sender_id:S.user.id,message_type:type,media_path:p});if(error)throw error}
async function toggleRecording(btn){if(S.recorder?.state==="recording"){S.recorder.stop();btn.classList.remove("recording");return}const stream=await navigator.mediaDevices.getUserMedia({audio:true});S.recordChunks=[];const rec=new MediaRecorder(stream);S.recorder=rec;btn.classList.add("recording");rec.ondataavailable=e=>e.data.size&&S.recordChunks.push(e.data);rec.onstop=async()=>{try{stream.getTracks().forEach(t=>t.stop());const blob=new Blob(S.recordChunks,{type:rec.mimeType||"audio/webm"}),file=new File([blob],"voice.webm",{type:blob.type}),p=await upload(file,"voice"),{error}=await sb.from("messages").insert({conversation_id:S.activeConversation,sender_id:S.user.id,message_type:"audio",media_path:p});if(error)throw error;toast("تم إرسال الرسالة الصوتية.")}catch(e){toast(e.message)}finally{S.recorder=null;S.recordChunks=[]}};rec.start();toast("جاري التسجيل… اضغط مرة أخرى للإرسال.")}

async function renderSerious(){const [{data:m},{data:c}]=await Promise.all([sb.from("matches").select("*").order("created_at",{ascending:false}),sb.from("marriage_cases").select("*").order("created_at",{ascending:false})]);$("#view").innerHTML=`<div class="section-head"><div><h2>Serious Mode™</h2><p>حين يصبح الإعجاب قرارًا جادًا، تتغير طبيعة الرحلة.</p></div><button class="button primary" id="startCase">ابدأ مع عهد</button></div><div class="grid2"><article class="card"><span class="chip">MATCHES</span><h3>${(m||[]).length} توافق متبادل</h3><p>تفتح المرحلة الجادة بعد اهتمام متبادل، لا قبل ذلك.</p></article><article class="card"><span class="chip">MARRIAGE PATH</span><h3>رسمي أو مسيار حيث ينطبق</h3><p>المسيار مسار زواج داخل Serious Mode، وليس قسم تعارف منفصلًا.</p></article><article class="card"><span class="chip">الخطّابة عهد</span><h3>إدارة الخطوات</h3><p>توافق، أسئلة أساسية، الأسرة أو الشخص الموثوق، ثم متابعة الحالة.</p></article><article class="card"><span class="chip">حالاتي</span><h3>${(c||[]).length} حالة</h3>${(c||[]).map(x=>`<button class="text-button open-case" data-id="${x.id}">${pathLabel(x.path)} · ${statusLabel(x.status)}</button>`).join("<br>")||"لم تفتح حالة بعد."}</article></div>`}
async function renderProfile(){const [{data:media},{count:following},{count:followers}]=await Promise.all([sb.from("profile_media").select("*").eq("user_id",S.user.id),sb.from("follows").select("*",{count:"exact",head:true}).eq("follower_id",S.user.id),sb.from("follows").select("*",{count:"exact",head:true}).eq("followed_id",S.user.id)]);$("#view").innerHTML=`<div class="profile-hero">${avatar(S.profile,"xl")}<div><span class="eyebrow">AHAD PROFILE</span><h2>${esc(S.profile.display_name)}</h2><p class="muted">${memberAge(S.profile)} · ${esc(city(S.profile))} · ${intent(S.profile.intent)}</p><div class="profile-stats"><div><b>${media?.length||0}</b><small>وسائط</small></div><div><b>${followers||0}</b><small>متابعون</small></div><div><b>${following||0}</b><small>أتابع</small></div></div></div></div><div class="vibe-grid"><article class="vibe-card"><span class="eyebrow">FAITH</span><h3>${esc(S.profile.faith_style||"—")}</h3><div class="vibe-bar"><i style="width:68%"></i></div></article><article class="vibe-card"><span class="eyebrow">LIFESTYLE</span><h3>${esc(S.profile.lifestyle_style||"—")}</h3><div class="vibe-bar"><i style="width:74%"></i></div></article><article class="vibe-card"><span class="eyebrow">CULTURE</span><h3>${esc(S.profile.culture_style||"—")}</h3><div class="vibe-bar"><i style="width:82%"></i></div></article><article class="vibe-card"><span class="eyebrow">INTENT</span><h3>${intent(S.profile.intent)}</h3><div class="vibe-bar"><i style="width:90%"></i></div></article></div><div class="grid2" style="margin-top:14px"><article class="card"><h3>ملفي وصوري</h3><p>${esc(S.profile.bio||"أضف نبذة حقيقية عنك.")}</p><button class="button soft" id="editProfile">تعديل AHAD VIBE</button> <button class="button primary" id="uploadProfileMedia">رفع صورة/فيديو</button></article><article class="card"><h3>الخصوصية والأمان</h3><p>تحكم بالظهور، تمويه الصور، المكالمات، الحظر والإبلاغ وحذف الحساب.</p><button class="button soft" id="privacySettings">إعدادات الخصوصية</button> <button class="button soft" id="browserNotifications">إشعارات المتصفح</button><br><br><button class="button danger" id="logout">تسجيل الخروج</button> <button class="button danger" id="deleteAccount">حذف الحساب</button></article></div>`}
async function renderStaff(){if(!S.staff){S.page="home";return render()}const [{data:c},{data:r}]=await Promise.all([sb.from("marriage_cases").select("*").order("created_at",{ascending:false}).limit(100),sb.from("reports").select("*").eq("status","open").order("created_at",{ascending:false}).limit(100)]);$("#view").innerHTML=`<div class="section-head"><div><h2>لوحة الخطّابة عهد</h2><p>إدارة الحالات والبلاغات والمحتوى.</p></div><button class="button primary" id="addPodcast">+ بودكاست</button></div><div class="grid2"><article class="card"><h3>طلبات الزواج · ${(c||[]).length}</h3><table class="admin-table"><tr><th>المسار</th><th>الحالة</th><th></th></tr>${(c||[]).map(x=>`<tr><td>${pathLabel(x.path)}</td><td><select class="case-status" data-id="${x.id}">${["requested","mutual_interest","guided","family_stage","contract_stage","completed","closed"].map(v=>`<option value="${v}" ${x.status===v?"selected":""}>${statusLabel(v)}</option>`).join("")}</select></td><td><button class="text-button staff-case" data-id="${x.id}">فتح</button></td></tr>`).join("")}</table></article><article class="card"><h3>بلاغات مفتوحة · ${(r||[]).length}</h3>${(r||[]).map(x=>`<div class="card"><b>${esc(x.reason)}</b><p>${esc(x.details||"")}</p><button class="button soft resolve-report" data-id="${x.id}" data-user="${x.reported_user_id}">إجراء</button></div>`).join("")||"لا توجد بلاغات."}</article></div>`}

function composer(kind="post"){modal(`<h2>${kind==="story"?"Story جديدة":kind==="reel"?"Reel جديد":"شارك لحظة"}</h2><form id="composerForm" data-kind="${kind}"><label>النص<textarea name="body"></textarea></label><label>صورة / فيديو<input name="media" type="file" accept="${kind==="reel"?"video/*":"image/*,video/*"}"></label>${kind==="post"?`<label>النوع<select name="type"><option value="post">منشور</option><option value="poll">Poll</option></select></label><label>خيارات Poll<input name="options" placeholder="نعم، لا، يعتمد"></label>`:""}<button class="button primary">نشر</button></form>`)}
async function openStory(id){const {data,error}=await sb.from("moments").select("*,profiles:author_id(display_name)").eq("id",id).single();if(error)throw error;await sb.from("story_views").upsert({moment_id:id,viewer_id:S.user.id});const isVideo=data.metadata?.mime?.startsWith("video"),media=data.media_path?(isVideo?`<video data-media="${esc(data.media_path)}" autoplay controls playsinline></video>`:`<img data-media="${esc(data.media_path)}">`):`<div style="font-size:60px">ع</div>`;modal(`<div class="story-viewer">${media}<div class="story-caption"><b>${esc(data.profiles?.display_name||"عضو")}</b><p>${esc(data.body||"")}</p></div></div>`,true);hydrateMedia($("#modal"))}
