async function openProfile(id){const p=S.profiles.find(x=>x.id===id);if(!p)return;modal(`<div style="display:flex;gap:16px;align-items:center">${avatar(p,"xl")}<div><span class="eyebrow">${compatibility(p)}% AHAD ENERGY</span><h2>${esc(p.display_name)} ${p.verified?"✓":""}</h2><p>${memberAge(p)} · ${esc(city(p))} · ${intent(p.intent)}</p></div></div><p>${esc(p.bio||"لا توجد نبذة بعد.")}</p><div class="tags">${[p.appearance_style,p.lifestyle_style,p.culture_style,p.faith_style,p.religion].filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join("")}</div><button class="button primary profile-like" data-id="${id}">♡ تعارف</button> <button class="button soft profile-follow" data-id="${id}">متابعة</button><hr><button class="button soft report-user" data-id="${id}">إبلاغ</button> <button class="button danger block-user" data-id="${id}">حظر</button>`);hydrateMedia($("#modal"))}
async function toggleLike(id){const {error}=await sb.from("profile_likes").insert({liker_id:S.user.id,liked_id:id});if(error?.code==="23505"){await sb.from("profile_likes").delete().eq("liker_id",S.user.id).eq("liked_id",id);toast("تم إلغاء الإعجاب.")}else if(error)throw error;else toast("تم الإعجاب. إذا كان متبادلًا ستفتح المحادثة تلقائيًا.")}
async function toggleFollow(id){const {error}=await sb.from("follows").insert({follower_id:S.user.id,followed_id:id});if(error?.code==="23505"){await sb.from("follows").delete().eq("follower_id",S.user.id).eq("followed_id",id);toast("ألغيت المتابعة.")}else if(error)throw error;else toast("تمت المتابعة.")}
