async function openMajlis(id){const {data:m,error}=await sb.from("majalis").select("*,majlis_presence(user_id,voice_role,muted)").eq("id",id).single();if(error)throw error;const joined=await sb.from("majlis_members").select("*").eq("majlis_id",id).eq("user_id",S.user.id).maybeSingle();modal(`<span class="eyebrow">AHAD MAJLIS™</span><h2>${esc(m.title)}</h2><p>${esc(m.description||"")}</p><p class="muted">${(m.majlis_presence||[]).length} في الصوت الآن</p><button class="button ${joined.data?"soft":"primary"}" id="joinMajlis" data-id="${id}">${joined.data?"أنت عضو":"انضم للمجلس"}</button> <button class="button primary" id="voiceMajlis" data-id="${id}">🎙 دخول الصوت</button> ${m.conversation_id?`<button class="button soft open-majlis-chat" data-conv="${m.conversation_id}">الدردشة النصية</button>`:""}<div id="voiceStage"></div>`,true)}
async function startGame(id){const {data:g,error}=await sb.from("games").select("*").eq("id",id).single();if(error)throw error;const qs=g.config?.questions||["هل تفضل التخطيط أم العفوية؟","هل السفر مهم؟","هل العائلة جزء كبير من يومك؟"];modal(`<h2>${esc(g.title)}</h2><form id="gameForm" data-id="${id}">${qs.map((q,i)=>`<label>${esc(q)}<select name="q${i}"><option>نعم</option><option>لا</option><option>يعتمد</option></select></label>`).join("")}<button class="button primary">حفظ</button></form>`)}
const groupForm=()=>modal(`<h2>مجموعة جديدة</h2><form id="groupForm"><label>اسم المجموعة<input name="title" required></label><label>الأعضاء<select name="members" multiple size="8">${S.profiles.map(p=>`<option value="${p.id}">${esc(p.display_name)}</option>`).join("")}</select></label><button class="button primary">إنشاء</button></form>`);

// Direct WebRTC calls
async function startDirectCall(conv,mode){const other=await otherMember(conv);if(!other)throw new Error("لا يوجد طرف آخر.");if(other.profiles?.allow_calls===false)throw new Error("هذا المستخدم عطّل طلبات المكالمات.");const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:mode==="video"}),pc=new RTCPeerConnection(RTC_CONFIG),callId=crypto.randomUUID();stream.getTracks().forEach(t=>pc.addTrack(t,stream));S.activeCall={pc,stream,conversationId:conv,callId,targetId:other.user_id,mode,pendingIce:[]};pc.onicecandidate=e=>e.candidate&&sb.from("call_signals").insert({conversation_id:conv,sender_id:S.user.id,target_id:other.user_id,call_id:callId,signal_type:"ice",payload:{candidate:e.candidate.toJSON(),scope:"direct"}});pc.ontrack=e=>{const v=$("#remoteCallMedia");if(v)v.srcObject=e.streams[0]};const offer=await pc.createOffer();await pc.setLocalDescription(offer);await sb.from("call_signals").insert({conversation_id:conv,sender_id:S.user.id,target_id:other.user_id,call_id:callId,signal_type:"offer",payload:{description:{type:offer.type,sdp:offer.sdp},mode,scope:"direct"}});showCall(`جاري الاتصال بـ ${esc(other.profiles?.display_name||"الطرف الآخر")}`,stream,mode)}
function showCall(title,stream,mode){modal(`<div class="call-panel"><span class="eyebrow">AHAD CALL</span><h2>${title}</h2><video id="remoteCallMedia" autoplay playsinline></video><video id="localCallMedia" autoplay muted playsinline style="${mode==="audio"?"display:none":""}"></video><div class="call-actions"><button class="button danger" id="hangupCall">إنهاء</button></div><p class="fine">WebRTC P2P. الشبكات المقيدة تحتاج TURN لضمان الاتصال عالميًا.</p></div>`,true);const v=$("#localCallMedia");if(v)v.srcObject=stream}
function listenIncomingCalls(){if(S.callChannel)sb.removeChannel(S.callChannel);S.callChannel=sb.channel(`calls:${S.user.id}`).on("postgres_changes",{event:"INSERT",schema:"public",table:"call_signals"},async p=>{const sig=p.new;if(sig.sender_id===S.user.id||sig.target_id!==S.user.id)return;if(sig.payload?.scope==="majlis"){await handleMajlisSignal(sig);return}if(sig.signal_type==="offer"){S.pendingCall=sig;const u=S.profiles.find(x=>x.id===sig.sender_id);modal(`<div class="call-panel"><span class="eyebrow">مكالمة واردة</span><h2>${esc(u?.display_name||"عضو من عهد")}</h2><p>${sig.payload?.mode==="video"?"مكالمة فيديو":"مكالمة صوتية"}</p><div class="call-actions"><button class="button primary" id="acceptCall">قبول</button><button class="button danger" id="declineCall">رفض</button></div></div>`)}else if(S.activeCall&&sig.call_id===S.activeCall.callId){if(sig.signal_type==="answer"){await S.activeCall.pc.setRemoteDescription(sig.payload.description);for(const c of S.activeCall.pendingIce.splice(0))await S.activeCall.pc.addIceCandidate(c)}if(sig.signal_type==="ice"){const c=sig.payload.candidate;if(S.activeCall.pc.remoteDescription)await S.activeCall.pc.addIceCandidate(c);else S.activeCall.pendingIce.push(c)}if(sig.signal_type==="hangup")endDirectCall(false)}}).subscribe()}
async function acceptCall(){const sig=S.pendingCall;if(!sig)return;const mode=sig.payload?.mode||"audio",stream=await navigator.mediaDevices.getUserMedia({audio:true,video:mode==="video"}),pc=new RTCPeerConnection(RTC_CONFIG);S.activeCall={pc,stream,conversationId:sig.conversation_id,callId:sig.call_id,targetId:sig.sender_id,mode,pendingIce:[]};S.pendingCall=null;stream.getTracks().forEach(t=>pc.addTrack(t,stream));pc.onicecandidate=e=>e.candidate&&sb.from("call_signals").insert({conversation_id:sig.conversation_id,sender_id:S.user.id,target_id:sig.sender_id,call_id:sig.call_id,signal_type:"ice",payload:{candidate:e.candidate.toJSON(),scope:"direct"}});pc.ontrack=e=>{const v=$("#remoteCallMedia");if(v)v.srcObject=e.streams[0]};await pc.setRemoteDescription(sig.payload.description);const ans=await pc.createAnswer();await pc.setLocalDescription(ans);await sb.from("call_signals").insert({conversation_id:sig.conversation_id,sender_id:S.user.id,target_id:sig.sender_id,call_id:sig.call_id,signal_type:"answer",payload:{description:{type:ans.type,sdp:ans.sdp},scope:"direct"}});showCall("مكالمة عهد",stream,mode)}
async function endDirectCall(send=true){const c=S.activeCall;if(!c){closeModal();return}if(send)await sb.from("call_signals").insert({conversation_id:c.conversationId,sender_id:S.user.id,target_id:c.targetId,call_id:c.callId,signal_type:"hangup",payload:{scope:"direct"}});c.stream?.getTracks().forEach(t=>t.stop());c.pc?.close();S.activeCall=null;closeModal()}

// Small multi-peer audio Majlis
async function joinMajlisVoice(id){const {data:m,error}=await sb.from("majalis").select("*").eq("id",id).single();if(error)throw error;if(!m.conversation_id)throw new Error("المجلس لم يجهز للصوت بعد.");if(S.majlisRoom)await leaveMajlisVoice();S.majlisStream=await navigator.mediaDevices.getUserMedia({audio:true});S.majlisRoom={majlisId:id,conversationId:m.conversation_id};await sb.from("majlis_presence").upsert({majlis_id:id,user_id:S.user.id,voice_role:"speaker",muted:false});const {data:prs}=await sb.from("majlis_presence").select("user_id").eq("majlis_id",id).neq("user_id",S.user.id);S.majlisChannel=sb.channel(`majlis:${id}`).on("postgres_changes",{event:"INSERT",schema:"public",table:"call_signals",filter:`conversation_id=eq.${m.conversation_id}`},async p=>{const sig=p.new;if(sig.target_id===S.user.id&&sig.payload?.scope==="majlis"&&sig.call_id===id)await handleMajlisSignal(sig)}).subscribe();for(const p of prs||[])await makeMajlisOffer(p.user_id);renderVoiceStage()}
async function makeMajlisPeer(remote){if(S.majlisPeers.has(remote))return S.majlisPeers.get(remote);const pc=new RTCPeerConnection(RTC_CONFIG),state={pc,pendingIce:[]};S.majlisPeers.set(remote,state);S.majlisStream.getTracks().forEach(t=>pc.addTrack(t,S.majlisStream));pc.onicecandidate=e=>e.candidate&&sb.from("call_signals").insert({conversation_id:S.majlisRoom.conversationId,sender_id:S.user.id,target_id:remote,call_id:S.majlisRoom.majlisId,signal_type:"ice",payload:{candidate:e.candidate.toJSON(),scope:"majlis"}});pc.ontrack=e=>{let a=$(`#remote-audio-${remote}`);if(!a){a=document.createElement("audio");a.id=`remote-audio-${remote}`;a.className="remote-audio";a.autoplay=true;$("#voiceStage")?.appendChild(a)}a.srcObject=e.streams[0]};return state}
async function makeMajlisOffer(remote){const st=await makeMajlisPeer(remote),o=await st.pc.createOffer();await st.pc.setLocalDescription(o);await sb.from("call_signals").insert({conversation_id:S.majlisRoom.conversationId,sender_id:S.user.id,target_id:remote,call_id:S.majlisRoom.majlisId,signal_type:"offer",payload:{description:{type:o.type,sdp:o.sdp},scope:"majlis",mode:"audio"}})}
async function handleMajlisSignal(sig){if(!S.majlisRoom||sig.call_id!==S.majlisRoom.majlisId)return;const st=await makeMajlisPeer(sig.sender_id);if(sig.signal_type==="offer"){await st.pc.setRemoteDescription(sig.payload.description);const a=await st.pc.createAnswer();await st.pc.setLocalDescription(a);await sb.from("call_signals").insert({conversation_id:S.majlisRoom.conversationId,sender_id:S.user.id,target_id:sig.sender_id,call_id:S.majlisRoom.majlisId,signal_type:"answer",payload:{description:{type:a.type,sdp:a.sdp},scope:"majlis"}});for(const c of st.pendingIce.splice(0))await st.pc.addIceCandidate(c)}else if(sig.signal_type==="answer"){await st.pc.setRemoteDescription(sig.payload.description);for(const c of st.pendingIce.splice(0))await st.pc.addIceCandidate(c)}else if(sig.signal_type==="ice"){const c=sig.payload.candidate;if(st.pc.remoteDescription)await st.pc.addIceCandidate(c);else st.pendingIce.push(c)}else if(sig.signal_type==="hangup"){st.pc.close();S.majlisPeers.delete(sig.sender_id)}}
function renderVoiceStage(){const e=$("#voiceStage");if(e&&S.majlisRoom)e.innerHTML=`<div class="voice-stage"><span class="eyebrow">VOICE MAJLIS · LIVE</span><h3>أنت داخل المجلس الصوتي</h3><p>هذه الغرفة Mesh للمجالس الصغيرة.</p><button class="button paper" id="toggleMajlisMute">كتم</button> <button class="button danger" id="leaveMajlisVoice">خروج</button></div>`}
async function leaveMajlisVoice(){if(!S.majlisRoom)return;for(const [id,st]of S.majlisPeers){await sb.from("call_signals").insert({conversation_id:S.majlisRoom.conversationId,sender_id:S.user.id,target_id:id,call_id:S.majlisRoom.majlisId,signal_type:"hangup",payload:{scope:"majlis"}});st.pc.close()}S.majlisStream?.getTracks().forEach(t=>t.stop());await sb.from("majlis_presence").delete().eq("majlis_id",S.majlisRoom.majlisId).eq("user_id",S.user.id);if(S.majlisChannel)await sb.removeChannel(S.majlisChannel);S.majlisPeers.clear();S.majlisRoom=null;S.majlisStream=null;S.majlisChannel=null;renderVoiceStage()}

async function caseDialog(id,staff=false){const [{data:c,error},{data:e}]=await Promise.all([sb.from("marriage_cases").select("*").eq("id",id).single(),sb.from("case_events").select("*").eq("case_id",id).order("created_at")]);if(error)throw error;modal(`<span class="eyebrow">SERIOUS MODE</span><h2>${pathLabel(c.path)}</h2><p><b>الحالة:</b> ${statusLabel(c.status)}</p><div class="timeline">${(e||[]).map(x=>`<div class="timeline-item"><b>${esc(x.event_type)}</b><small class="muted">${dateText(x.created_at)}</small>${x.note?`<p>${esc(x.note)}</p>`:""}</div>`).join("")||"لا أحداث بعد."}</div>${staff?`<form id="caseNoteForm" data-id="${id}"><label>ملاحظة من الخطّابة<textarea name="note"></textarea></label><button class="button primary">إضافة للسجل</button></form>`:""}`)}
async function startCaseDialog(){const {data:m}=await sb.from("matches").select("*").order("created_at",{ascending:false});if(!m?.length){toast("تحتاج Match متبادلًا أولًا.");return}const opts=m.map(x=>{const id=x.user_a===S.user.id?x.user_b:x.user_a,p=S.profiles.find(z=>z.id===id);return `<option value="${id}">${esc(p?.display_name||"توافق")}</option>`});modal(`<h2>ابدأ Serious Mode</h2><form id="caseForm"><label>الشخص<select name="partner">${opts.join("")}</select></label><label>المسار<select name="path"><option value="official">زواج رسمي</option><option value="misyar">مسيار حيث ينطبق</option><option value="discuss">نناقشه مع عهد</option></select></label><button class="button primary">فتح الحالة</button></form>`)}
const podcastForm=()=>modal(`<h2>إضافة حلقة بودكاست</h2><form id="podcastForm"><label>العنوان<input name="title" required></label><label>الفئة<select name="category"><option>ديني</option><option>اجتماعي</option><option>ثقافي</option><option>توعوي</option></select></label><label>الوصف<textarea name="description"></textarea></label><label>ملف الصوت<input name="audio" type="file" accept="audio/*" required></label><label>الغلاف<input name="cover" type="file" accept="image/*"></label><button class="button primary">رفع ونشر</button></form>`);
const privacyDialog=()=>modal(`<h2>الخصوصية</h2><form id="privacyForm"><label class="toggle"><input name="discover" type="checkbox" ${S.profile.is_discoverable?"checked":""}><span></span> الظهور في Discover</label><label class="toggle"><input name="online" type="checkbox" ${S.profile.show_online?"checked":""}><span></span> إظهار الاتصال</label><label class="toggle"><input name="age" type="checkbox" ${S.profile.show_age?"checked":""}><span></span> إظهار العمر</label><label class="toggle"><input name="city" type="checkbox" ${S.profile.show_city?"checked":""}><span></span> إظهار المدينة</label><label class="toggle"><input name="blur" type="checkbox" ${S.profile.blur_photos_until_match?"checked":""}><span></span> تمويه الصور حتى Match</label><label class="toggle"><input name="calls" type="checkbox" ${S.profile.allow_calls?"checked":""}><span></span> السماح بالمكالمات</label><button class="button primary">حفظ</button></form>`);
const editProfileDialog=()=>modal(`<h2>تعديل AHAD VIBE™</h2><form id="editProfileForm"><label>النبذة<textarea name="bio">${esc(S.profile.bio||"")}</textarea></label><label>النية<select name="intent"><option value="exploring" ${S.profile.intent==="exploring"?"selected":""}>أكتشف</option><option value="serious" ${S.profile.intent==="serious"?"selected":""}>جاد</option><option value="marriage" ${S.profile.intent==="marriage"?"selected":""}>زواج</option></select></label><label>المظهر<input name="appearance" value="${esc(S.profile.appearance_style||"")}"></label><label>الاهتمامات<input name="interests" value="${esc((S.profile.interests||[]).join("، "))}"></label><button class="button primary">حفظ</button></form>`);
async function notificationsDialog(){const {data}=await sb.from("notifications").select("*").order("created_at",{ascending:false}).limit(60);modal(`<h2>الإشعارات</h2>${(data||[]).map(n=>`<article class="card"><b>${esc(n.title)}</b><p>${esc(n.body||"")}</p></article>`).join("")||"لا توجد إشعارات."}`);await sb.from("notifications").update({read_at:new Date().toISOString()}).eq("user_id",S.user.id).is("read_at",null);loadNotificationCount()}
async function loadNotificationCount(){const {count}=await sb.from("notifications").select("*",{count:"exact",head:true}).eq("user_id",S.user.id).is("read_at",null);$("#notificationBadge").textContent=count||0;$("#notificationBadge").classList.toggle("hidden",!count)}
function subscribeGlobal(){if(S.globalChannel)sb.removeChannel(S.globalChannel);S.globalChannel=sb.channel(`ahad:${S.user.id}`).on("postgres_changes",{event:"INSERT",schema:"public",table:"notifications",filter:`user_id=eq.${S.user.id}`},p=>{loadNotificationCount();toast(p.new.title||"إشعار جديد");if(Notification.permission==="granted")new Notification(p.new.title||"عهد",{body:p.new.body||""})}).subscribe();loadNotificationCount()}
async function deleteAccount(){if(!confirm("سيتم حذف حسابك وبياناتك المرتبطة نهائيًا. هل تريد المتابعة؟"))return;const phrase=prompt("للتأكيد اكتب: DELETE MY AHAD ACCOUNT");if(phrase!=="DELETE MY AHAD ACCOUNT")return;const {data:{session}}=await sb.auth.getSession(),r=await fetch(DELETE_ACCOUNT_FUNCTION,{method:"POST",headers:{authorization:`Bearer ${session.access_token}`,"content-type":"application/json"},body:JSON.stringify({confirm:phrase})}),b=await r.json().catch(()=>({}));if(!r.ok)throw new Error(b.error||"فشل حذف الحساب");await sb.auth.signOut();location.reload()}

